import{_ as t,o as a,c as l,a0 as i}from"./chunks/framework.jwovEGr5.js";const _=JSON.parse('{"title":"网络协议","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"概念学习/网页制作/网络协议.md","filePath":"概念学习/网页制作/网络协议.md"}'),o={name:"概念学习/网页制作/网络协议.md"};function r(n,e,d,h,s,c){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="网络协议" tabindex="-1">网络协议 <a class="header-anchor" href="#网络协议" aria-label="Permalink to &quot;网络协议&quot;">​</a></h1><p>网络协议是网络设备之间通信的一套共同约定（规则、格式、时序），可以让不同厂商、不同系统的设备能看懂互相发送的数据</p><h2 id="http-https" tabindex="-1">HTTP/HTTPS <a class="header-anchor" href="#http-https" aria-label="Permalink to &quot;HTTP/HTTPS&quot;">​</a></h2><p>客户端与服务器之间的通信协议</p><h3 id="http状态码" tabindex="-1">HTTP状态码 <a class="header-anchor" href="#http状态码" aria-label="Permalink to &quot;HTTP状态码&quot;">​</a></h3><ul><li>2xx 成功 <ul><li>200 OK：查询成功</li><li>201 Created：POST创建资源成功</li></ul></li><li>3xx 重定向</li><li>4xx 客户端错误 <ul><li>400 Bad Request：参数格式错误</li><li>401 Unauthorized：未认证，缺少token/token失效</li><li>403 Forbidden：认证成功，但没有权限访问</li><li>404 Not Found：接口地址不存在</li><li>405 Method Not Allowed：接口不支持这个请求方法，例如接口只支持GET</li></ul></li><li>5xx 服务端错误 <ul><li>500 Internal Server Error：服务内部异常</li><li>503 Service Unavailable：服务不可用、宕机</li></ul></li></ul><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to &quot;WebSocket&quot;">​</a></h2><p>实现客户端与服务器的双向实时通信（如聊天应用）</p>',8)])])}const p=t(o,[["render",r]]);export{_ as __pageData,p as default};
